    }

    // Allocate memory for IV and key
    result.iv = (unsigned char*)malloc(DES_BLOCK_SIZE);
    result.key = (unsigned char*)malloc(DES_KEY_SIZE);
    if (!result.iv || !result.key) {
        free(result.iv);
        free(result.key);
        return result;
